pub struct SpinLock { locked: AtomicBool }

impl SpinLock {
    pub fn lock(&self) {
        while self.locked.swap(true, Acquire) {
            std::hint::spin_loop();
        }
    }
    pub fn unlock(&self) {
        self.locked.store(false, Release);
    }
}

#include <linux/futex.h>
#include <stdint.h>
#include <sys/syscall.h>
#include <unistd.h>

static long futex_wait(uint32_t *w, uint32_t expected) {
    // Sleeps only if *w == expected, checked atomically in the kernel.
    return syscall(SYS_futex, w, FUTEX_WAIT_PRIVATE, expected, NULL);
}

static long futex_wake(uint32_t *w, int n) {
    // Returns the number of waiters actually woken.
    return syscall(SYS_futex, w, FUTEX_WAKE_PRIVATE, n);
}

fn lock(s: &AtomicU32) {
    if s.compare_exchange(0, 1, Acquire, Relaxed).is_err() {
        while s.swap(2, Acquire) != 0 {
            futex_wait(s, 2);
        }
    }
}

fn unlock(s: &AtomicU32) {
    if s.swap(0, Release) == 2 {
        futex_wake(s, 1);
    }
}

fn spin(&self) -> State {
    let mut spin = 100;
    loop {
        // Only load while spinning, to be easier on the caches.
        let state = self.futex.load(Relaxed);
        // Stop when UNLOCKED, or when CONTENDED (someone already sleeps).
        if state != LOCKED || spin == 0 {
            return state;
        }
        crate::hint::spin_loop();
        spin -= 1;
    }
}
